mapper.select:
SELECT e.category_code AS category_code, c.label AS category_label, SUM(e.amount) AS amount FROM expenses e JOIN trip_members tm ON e.payer_member_id = tm.id JOIN expense_categories c ON e.category_code = c.code WHERE tm.user_id = #{userId}
AND e.spent_at >= #{from}
AND e.spent_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
GROUP BY e.category_code, c.label, c.sort_order ORDER BY c.sort_order ASC

mapper.insert:
INSERT INTO expenses (
    trip_id, name, emoji, amount, spent_at,
    category_code, source, payer_name, split_mode, memo
) VALUES (
    #{tripId}, #{name}, #{emoji}, #{amount}, #{spentAt},
    #{categoryCode}, #{source}, #{payerName}, #{splitMode}, #{memo}
)
